          "lacuna": "ēs",
          "inter": " deōs vid",
          "lacuna2": "ēre",
          "suffix": " nōn possunt.",
          "explicatio": "Nōminātīvus plūrālis (hominēs) et īnfīnītīvus āctīvī (vidēre)."
